lemma CountBound(t: string, c: char)
  ensures multiset(t)[c] <= |t|
{
  if |t| > 0 {
    assert t == t[..|t| - 1] + [t[|t| - 1]];
    CountBound(t[..|t| - 1], c);
  }
}

lemma NotAllSame(s: string, i: nat)
  requires 0 < i < |s| && s[i] != s[0]
  ensures multiset(s)[s[0]] < |s|
{
  var c := s[0];
  assert s == s[..i] + [s[i]] + s[i + 1..];
  assert multiset(s) == multiset(s[..i]) + multiset([s[i]]) + multiset(s[i + 1..]);
  CountBound(s[..i], c);
  CountBound(s[i + 1..], c);
}

method allCharactersSame(s: string) returns (result: bool)
  ensures result ==> forall i, j :: 0 <= i < j < |s| ==> s[i] == s[j]
  ensures !result ==> |s| > 0 && multiset(s)[s[0]] < |s|
{
  if |s| == 0 {
    return true;
  }
  var i := 1;
  while i < |s|
    invariant 1 <= i <= |s|
    invariant forall k :: 0 <= k < i ==> s[k] == s[0]
  {
    if s[i] != s[0] {
      NotAllSame(s, i);
      return false;
    }
    i := i + 1;
  }
  return true;
}

